package dk.revo.revoextraction;
import dk.revo.revocultivation.*;
import dk.revo.revostorage.*;
import net.minecraft.core.*;
import net.minecraft.gametest.framework.*;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.world.item.*;
import net.minecraft.world.item.crafting.*;
import net.minecraft.world.inventory.ClickType;
import net.neoforged.neoforge.gametest.*;
@GameTestHolder("revoextraction") @PrefixGameTestTemplate(false)
public class ProgressionExpansionTests {
 static Item item(String s){return ProgressionBridgeTests.item(s);}
 static void check(GameTestHelper h,boolean ok,String why){h.assertTrue(ok,why);}
 @GameTest(template="drill_test",timeoutTicks=100)
 public static void allNewMobsAndBurnerCapture(GameTestHelper h){
  for(var kind:new MachineKind[]{MachineKind.HARVESTER,MachineKind.STEEL_HARVESTER})for(int i=0;i<kind.harvesterPrograms().length;i++){
   var m=ProgressionBridgeTests.farm(h,kind,i);check(h,!m.captureBurner(),"No instant burner fills");ProgressionBridgeTests.ticks(m,kind.ticks);var expected=MachineKind.products(kind.harvesterPrograms()[i]);for(var s:expected)check(h,ProgressionBridgeTests.count(m.outputs,s.getItem())>=s.getCount(),"Actual mob product "+s);check(h,m.containedMob()!=null,"Every mob renders a valid contained entity");
   if(m.program()==24){var saved=m.saveWithoutMetadata(h.getLevel().registryAccess());m.loadWithComponents(saved,h.getLevel().registryAccess());check(h,m.captureBurner()&&!m.captureBurner(),"One saved credit per Blaze cycle");}
  }h.succeed();
 }
 @GameTest(template="drill_test",timeoutTicks=100)
 public static void allNewGreenhouseProgramsRetainStarters(GameTestHelper h){
  h.getLevel().setDayTime(1000);for(int program:new int[]{14,15,16}){var m=ProgressionBridgeTests.farm(h,MachineKind.GREENHOUSE,0);m.inputs.setStackInSlot(0,MachineKind.starter(program));m.water.fill(new net.neoforged.neoforge.fluids.FluidStack(net.minecraft.world.level.material.Fluids.WATER,1000),net.neoforged.neoforge.fluids.capability.IFluidHandler.FluidAction.EXECUTE);ProgressionBridgeTests.ticks(m,400);check(h,m.program()==program&&ProgressionBridgeTests.count(m.outputs,MachineKind.starter(program).getItem())==3,"Three crop outputs");check(h,m.inputs.getStackInSlot(0).getCount()==1&&m.water.getFluidAmount()==750,"Retained starter and paid water");}h.succeed();
 }
 @GameTest(template="drill_test",timeoutTicks=100)
 public static void loadedRecipeBridgesAndBucketRemainder(GameTestHelper h){
  for(String id:new String[]{"milling/raw_gold","empty_blaze_burner","sugar_cane_starter","kelp_starter","cactus_starter","beetroot_starter","electric_drill","deep_survey_core","synthetic_netherrack","synthetic_soul_sand"})check(h,h.getLevel().getRecipeManager().byKey(ResourceLocation.parse("revoextraction:"+id)).isPresent(),"Recipe loads: "+id);
  var recipe=(CraftingRecipe)h.getLevel().getRecipeManager().byKey(ResourceLocation.parse("revoextraction:kelp_starter")).orElseThrow().value();var input=CraftingInput.of(3,1,java.util.List.of(new ItemStack(item("revocultivation:compost")),new ItemStack(Items.WHEAT_SEEDS),new ItemStack(Items.WATER_BUCKET)));check(h,recipe.matches(input,h.getLevel()),"Kelp uses actual registered compost");check(h,recipe.assemble(input,h.getLevel().registryAccess()).is(Items.KELP),"Kelp result");check(h,recipe.getRemainingItems(input).stream().anyMatch(s->s.is(Items.BUCKET)),"Returns empty bucket");
  for(String id:new String[]{"revostorage:chest_drive","revostorage:crafting_terminal","revocultivation:trading_colony","modern_industrialization:electric_age/machine/lv_steam_turbine_asbl","modern_industrialization:electric_age/circuit/craft/lv_circuit_asbl"})check(h,h.getLevel().getRecipeManager().byKey(ResourceLocation.parse(id)).isPresent(),"Native crafting route "+id);h.succeed();
 }
 @GameTest(template="drill_test",timeoutTicks=100)
 public static void electricGeologyPowerBlockingDeepAndPersistence(GameTestHelper h){var l=h.getLevel();var pos=h.absolutePos(new BlockPos(2,2,2));l.setBlockAndUpdate(pos,RevoExtraction.ELECTRIC.get().defaultBlockState());var e=(ElectricDrillEntity)l.getBlockEntity(pos);
  ElectricDrillEntity.tick(l,pos,e.getBlockState(),e);check(h,e.work==0,"No free power");
  for(int program=0;program<=4;program++){e.program=program;e.work=0;e.energy=32000;var expected=e.output().getItem();check(h,expected!=Items.AIR,"Real registered ore");for(int t=0;t<200;t++)ElectricDrillEntity.tick(l,pos,e.getBlockState(),e);check(h,ProgressionBridgeTests.count(e.items,expected)>0&&e.energy==28800,"16 EU/t mining program "+program);}
  e.program=5;e.work=0;e.energy=32000;e.items.setStackInSlot(1,new ItemStack(Items.WATER_BUCKET));for(int t=0;t<200;t++)ElectricDrillEntity.tick(l,pos,e.getBlockState(),e);check(h,ProgressionBridgeTests.count(e.items,Items.ICE)==1&&e.items.getStackInSlot(1).is(Items.BUCKET),"Glacial water paid and bucket returned");
  e.program=6;e.work=0;e.energy=32000;ElectricDrillEntity.tick(l,pos,e.getBlockState(),e);check(h,e.work==0,"Deep core required");e.items.setStackInSlot(0,new ItemStack(RevoExtraction.SURVEY_CORE.get()));e.cycle=63;e.work=1199;ElectricDrillEntity.tick(l,pos,e.getBlockState(),e);check(h,ProgressionBridgeTests.count(e.items,Items.ANCIENT_DEBRIS)==1&&e.cycle==64,"Rare deep output");var tag=e.saveWithoutMetadata(l.registryAccess());e.loadWithComponents(tag,l.registryAccess());check(h,e.cycle==64&&e.program==6,"Deep cursor saved");for(int i=2;i<11;i++)e.items.setStackInSlot(i,new ItemStack(Items.COBBLESTONE,64));int power=e.energy;ElectricDrillEntity.tick(l,pos,e.getBlockState(),e);check(h,e.energy==power&&e.work==0,"Full output pauses energy and work");h.succeed();}
 @GameTest(template="drill_test",timeoutTicks=100)
 public static void tradingColonyConsumesExactlySixteen(GameTestHelper h){var l=h.getLevel();var pos=h.absolutePos(new BlockPos(2,2,2));l.setBlockAndUpdate(pos,RevoCultivation.TRADE.get().defaultBlockState());var e=(TradingColony.Entity)l.getBlockEntity(pos);e.items.setStackInSlot(0,new ItemStack(Items.PAPER,32));for(int t=0;t<200;t++)TradingColony.Entity.tick(l,pos,e.getBlockState(),e);check(h,e.items.getStackInSlot(0).getCount()==16&&e.items.getStackInSlot(26).is(Items.EMERALD),"16 paper = 1 emerald");h.succeed();}
 @GameTest(template="drill_test",timeoutTicks=100)
 public static void nineDiamondChestsNetworkAndPersistence(GameTestHelper h){var l=h.getLevel();var pos=h.absolutePos(new BlockPos(2,2,2));l.setBlockAndUpdate(pos,RevoStorage.DRIVE.get().defaultBlockState());l.setBlockAndUpdate(pos.east(),RevoStorage.TERMINAL.get().defaultBlockState());var e=(StorageEntity)l.getBlockEntity(pos);var terminal=(StorageEntity)l.getBlockEntity(pos.east());var diamond=item("ironchest:diamond_chest");check(h,diamond!=Items.AIR,"Iron Chests integration installed");for(int i=0;i<9;i++)e.chests.setStackInSlot(i,new ItemStack(diamond));check(h,e.capacity()==972&&terminal.networkItems().getSlots()==972,"Nine native diamond chest capacities");check(h,terminal.insert(new ItemStack(Items.DIAMOND,64),false).isEmpty(),"Network insert");check(h,e.chests.extractItem(0,1,false).isEmpty(),"Nonempty bay locks chest");check(h,terminal.take(new ItemStack(Items.DIAMOND),32,true).getCount()==32&&terminal.take(new ItemStack(Items.DIAMOND),32,false).getCount()==32,"Simulation does not extract");var tag=e.saveWithoutMetadata(l.registryAccess());e.loadWithComponents(tag,l.registryAccess());check(h,ProgressionBridgeTests.count(terminal.networkItems(),Items.DIAMOND)==32,"Real saved inventory");terminal.take(new ItemStack(Items.DIAMOND),32,false);check(h,!e.chests.extractItem(0,1,false).isEmpty()&&terminal.networkItems().getSlots()==864,"Empty bay removes without phantom slots");h.succeed();}
 @GameTest(template="drill_test",timeoutTicks=100)
 public static void terminalTransferCraftRemaindersChargeAndSharedGrid(GameTestHelper h){var l=h.getLevel();var pos=h.absolutePos(new BlockPos(2,2,2));l.setBlockAndUpdate(pos,RevoStorage.DRIVE.get().defaultBlockState());l.setBlockAndUpdate(pos.east(),RevoStorage.TERMINAL.get().defaultBlockState());var drive=(StorageEntity)l.getBlockEntity(pos);drive.chests.setStackInSlot(0,new ItemStack(Items.CHEST));check(h,drive.capacity()==27,"Vanilla chest capacity="+StorageEntity.chestCapacity(new ItemStack(Items.CHEST))+" components="+new ItemStack(Items.CHEST).getComponents());var e=(StorageEntity)l.getBlockEntity(pos.east());check(h,e.insert(new ItemStack(Items.OAK_LOG,3),false).isEmpty(),"Initial log insert; slots="+e.networkItems().getSlots());check(h,ProgressionBridgeTests.count(e.networkItems(),Items.OAK_LOG)==3,"Initial stored logs");var player=net.neoforged.neoforge.common.util.FakePlayerFactory.getMinecraft(l);player.teleportTo(pos.getX()+1,pos.getY(),pos.getZ());var menu=new StorageMenu(1,player.getInventory(),e);check(h,l.getRecipeManager().byKey(ResourceLocation.parse("minecraft:oak_planks")).isPresent(),"Vanilla oak planks recipe exists");check(h,e.networkItems().getSlots()==27&&ProgressionBridgeTests.count(e.networkItems(),Items.OAK_LOG)==3,"Logs inserted into connected drive: slots="+e.networkItems().getSlots()+" logs="+ProgressionBridgeTests.count(e.networkItems(),Items.OAK_LOG));menu.transfer(ResourceLocation.parse("minecraft:oak_planks"),false);check(h,menu.craft.getItem(0).is(Items.OAK_LOG),"Recipe transfer from whole network");check(h,menu.slots.getFirst().getItem().is(Items.OAK_PLANKS),"Native crafting result");menu.clicked(0,0,ClickType.PICKUP,player);check(h,menu.getCarried().isEmpty(),"No crafting without winding");e.wind();menu.clicked(0,0,ClickType.PICKUP,player);check(h,menu.getCarried().is(Items.OAK_PLANKS)&&menu.getCarried().getCount()==4&&e.charge==255,"Craft produces four planks and spends one charge");check(h,menu.craft.getItem(0).is(Items.OAK_LOG),"Grid refills after craft");menu.setCarried(ItemStack.EMPTY);menu.quickMoveStack(player,0);check(h,player.getInventory().countItem(Items.OAK_PLANKS)==4,"Shift-click crafting");e.insert(new ItemStack(Items.DIAMOND),false);menu.search="@minecraft";check(h,!menu.entries().isEmpty(),"Mod search");menu.search="impossible";check(h,menu.entries().isEmpty(),"Search hides unmatched items");var tag=e.saveWithoutMetadata(l.registryAccess());e.loadWithComponents(tag,l.registryAccess());check(h,e.craftingItems.getFirst().is(Items.OAK_LOG)&&e.charge==254,"Persistent shared grid and spring");h.succeed();}
 @GameTest(template="drill_test",timeoutTicks=100)
 public static void firstPoweredGreenhouseHarvestAndBackpressure(GameTestHelper h){var l=h.getLevel();l.setDayTime(1000);l.setWeatherParameters(100000,0,false,false);l.setRainLevel(0);var kind=MachineKind.IRON_GREENHOUSE;var pos=h.absolutePos(new BlockPos(4,2,3));l.setBlockAndUpdate(pos,kind.controller().defaultBlockState().setValue(FarmController.FACING,Direction.NORTH));var m=(FarmMachine)l.getBlockEntity(pos);
  for(int x=-2;x<=2;x++)for(int y=0;y<3;y++)for(int z=-2;z<=2;z++){var part=kind.part(x,y,z);var state=kind.block(part).defaultBlockState();if(part==MachineKind.Part.CONTROLLER)state=state.setValue(FarmController.FACING,Direction.NORTH);if(part==MachineKind.Part.HATCH)state=state.setValue(FarmHatch.FACING,Direction.EAST);if(part==MachineKind.Part.POWER)state=state.setValue(net.minecraft.world.level.block.state.properties.BlockStateProperties.FACING,Direction.SOUTH);l.setBlockAndUpdate(m.at(x,y,z),state);}
  check(h,m.checkStructure(),"First electric greenhouse forms");m.inputs.setStackInSlot(0,new ItemStack(Items.SUGAR_CANE));m.water.fill(new net.neoforged.neoforge.fluids.FluidStack(net.minecraft.world.level.material.Fluids.WATER,1000),net.neoforged.neoforge.fluids.capability.IFluidHandler.FluidAction.EXECUTE);m.receiveEu(1600,false);ProgressionBridgeTests.ticks(m,200);check(h,ProgressionBridgeTests.count(m.outputs,Items.SUGAR_CANE)==3&&m.water.getFluidAmount()==750&&m.energy()==0,"One real harvest consumes 1600 EU and 250 mB");for(int i=0;i<9;i++)m.outputs.setStackInSlot(i,new ItemStack(Items.COBBLESTONE,64));m.receiveEu(1600,false);ProgressionBridgeTests.ticks(m,20);check(h,m.energy()==1600&&m.water.getFluidAmount()==750&&m.state()==5,"Full greenhouse pauses power and water");h.succeed();
 }
 @GameTest(template="drill_test",timeoutTicks=100)
 public static void terminalKineticChargingAndHopperCapability(GameTestHelper h){var l=h.getLevel();var pos=h.absolutePos(new BlockPos(2,2,2));l.setBlockAndUpdate(pos,RevoStorage.DRIVE.get().defaultBlockState());l.setBlockAndUpdate(pos.east(),RevoStorage.TERMINAL.get().defaultBlockState());var drive=(StorageEntity)l.getBlockEntity(pos);drive.chests.setStackInSlot(0,new ItemStack(Items.CHEST));var terminal=(StorageEntity)l.getBlockEntity(pos.east());var handler=l.getCapability(net.neoforged.neoforge.capabilities.Capabilities.ItemHandler.BLOCK,pos.east(),Direction.DOWN);check(h,handler!=null&&handler.getSlots()==27,"Hopper sees connected storage");check(h,net.neoforged.neoforge.items.ItemHandlerHelper.insertItemStacked(handler,new ItemStack(Items.IRON_INGOT,12),false).isEmpty(),"Hopper inserts items");check(h,ProgressionBridgeTests.count(terminal.networkItems(),Items.IRON_INGOT)==12,"Hopper items arrive in drive");var shaftPos=pos.east(2);l.setBlockAndUpdate(shaftPos,com.simibubi.create.AllBlocks.CREATIVE_MOTOR.getDefaultState());var shaft=(com.simibubi.create.content.kinetics.base.KineticBlockEntity)l.getBlockEntity(shaftPos);shaft.setSpeed(32);int delay=20-(int)(l.getGameTime()%20);h.runAfterDelay(delay,()->{StorageEntity.tick(l,pos.east(),terminal.getBlockState(),terminal);check(h,terminal.charge>=32,"Actual powered Create motor recharges spring");h.succeed();});
 }
 @GameTest(template="drill_test",timeoutTicks=100)
 public static void terminalCraftReturnsWaterBucket(GameTestHelper h){var l=h.getLevel();var pos=h.absolutePos(new BlockPos(2,2,2));l.setBlockAndUpdate(pos,RevoStorage.DRIVE.get().defaultBlockState());l.setBlockAndUpdate(pos.east(),RevoStorage.TERMINAL.get().defaultBlockState());var drive=(StorageEntity)l.getBlockEntity(pos);drive.chests.setStackInSlot(0,new ItemStack(Items.CHEST));var e=(StorageEntity)l.getBlockEntity(pos.east());e.wind();for(var item:new Item[]{item("revocultivation:compost"),Items.WHEAT_SEEDS,Items.WATER_BUCKET})e.insert(new ItemStack(item),false);var player=net.neoforged.neoforge.common.util.FakePlayerFactory.getMinecraft(l);player.getInventory().clearContent();var menu=new StorageMenu(1,player.getInventory(),e);menu.transfer(ResourceLocation.parse("revoextraction:kelp_starter"),false);menu.clicked(0,0,ClickType.PICKUP,player);check(h,menu.getCarried().is(Items.KELP),"Actual terminal crafts kelp");check(h,menu.craft.getItems().stream().anyMatch(stack->stack.is(Items.BUCKET))||player.getInventory().countItem(Items.BUCKET)>0,"Native ResultSlot returns bucket");check(h,e.charge==255,"One operation charged");h.succeed();}
}
